import java.util.Scanner;

public class Main {

    static void swap(int x, int y) {
        int tmp = x;
        x = y;
        y = tmp;
    }

    static void swap(int[] pair) {
        int tmp = pair[0];
        pair[0] = pair[1];
        pair[1] = tmp;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();

        int p = a;
        int q = b;
        swap(p, q);
        System.out.println("基本型 " + p + " " + q);

        int[] pair = {a, b};
        swap(pair);
        System.out.println("配列 " + pair[0] + " " + pair[1]);
    }
}

