import java.util.*;

public class Main {
    static String classify(int n) {
        for (int i = 2; i * i <= n; i++) if (n % i == 0) return "composite";
        return "prime";
    }

    public static void main(String[] args) {
        System.out.println(classify(new Scanner(System.in).nextInt()));
    }
}

